async function sadiTefsirYukle(sNo, aNo, panel) {
  const icerik = panel.querySelector('.ayet-ekstra-icerik');
  const sureData = PDF_TEFSIR_DB[String(sNo)];
  const ayetData = sureData ? sureData[String(aNo)] : null;

  if (ayetData && (ayetData.tefsir || ayetData.meal)) {
    icerik.innerHTML = '';

    if (ayetData.tefsir && ayetData.tefsir.trim()) {
      const tefsirEl = document.createElement('div');
      tefsirEl.style.cssText = 'font-size:13.5px;line-height:1.9;color:var(--text);white-space:pre-wrap;';
      tefsirEl.textContent = ayetData.tefsir.trim();
      icerik.appendChild(tefsirEl);
    } else {
      icerik.textContent = 'Bu âyet için tefsir notu bulunmuyor.';
    }
    icerik.classList.remove('yukl');
  } else {
    icerik.textContent = 'Bu sûre için henüz tefsir eklenmemiş.';
    icerik.classList.remove('yukl');
  }
}

