//  FAWAZAHMED0 CDN — Sûre bazlı meal + Arapça metin
// ════════════════════════════════════════
const fawazSureCache = {};
const kurancilarArCache = {};

// Tekil ayet için Diyanet meali (fawaz cache üzerinden)
async function _fawazAyetAl(sNo, aNo) {
  try {
    const sureler = await _fawazSureAl(sNo);
    if (!sureler) return null;
    const ay = sureler.find(a => a.verse === aNo || a.verse === String(aNo));
    return ay ? ay.text : null;
  } catch(e) { return null; }
}

// Mehmet Okuyan — api.acikkuran.com (author=107), sure bazlı cache
const okuyanSureCache = {};
async function _okuyanSureAl(sNo) {
  if (okuyanSureCache[sNo]) return okuyanSureCache[sNo];
  try {
    const url = 'https://api.acikkuran.com/surah/' + sNo + '?author=107';
    const r = await fetch(url);
    const d = await r.json();
    const ayetler = d.data && d.data.verses ? d.data.verses : [];
    okuyanSureCache[sNo] = ayetler;
    return ayetler;
  } catch(e) {
    okuyanSureCache[sNo] = null;
    return null;
  }
}

async function _fawazSureAl(sNo) {
  if (fawazSureCache[sNo]) return fawazSureCache[sNo];
  try {
    // fawazahmed0: tüm Kur'an tek JSON — sûre no + âyet no ile filtrele
    const url = 'https://cdn.jsdelivr.net/gh/fawazahmed0/quran-api@1/editions/tur-diyanetisleri/' + sNo + '.json';
    const r = await fetch(url);
    const d = await r.json();
    // Format: {chapter: [{verse:1, text:"..."}, ...]}
    const ayetler = d.chapter || d.verses || d;
    // verse alanını normalleştir
    const normalize = Array.isArray(ayetler)
      ? ayetler.map(a => ({ verse: a.verse || a.verseNumber || a.id, text: a.text || a.translation }))
      : [];
    fawazSureCache[sNo] = normalize;
    return normalize;
  } catch(e) {
    fawazSureCache[sNo] = null;
    return null;
  }
}

// ════════════════════════════════════════
//  ÖZEL ARAPÇA METİN (GitHub'dan, salt-okunur, mevcut API'nin YERİNE geçer)
//  Depolama: localStorage 'ozel_arapca_SURENO' = { "1": "arapça metin", "2": "...", ... }
//  Format: Arapça satır, altında SADECE "N." şeklinde numara satırı
// ════════════════════════════════════════

function _ozelArapcaAnahtari(sureNo) {
  return 'ozel_arapca_' + sureNo;
}

function _ozelArapcaKaynaklariGetir() {
  try { return JSON.parse(localStorage.getItem('ozel_arapca_kaynaklari') || '[]'); } catch(e) { return []; }
}
function _ozelArapcaKaynaklariKaydet(arr) {
  localStorage.setItem('ozel_arapca_kaynaklari', JSON.stringify(arr));
}

// Format: her satır ya Arapça metin ya da tek başına "N." numarasıdır.
// Bir Arapça satırdan sonra gelen ilk "N." o Arapça metnin numarasıdır.
function _ozelArapcaParseEt(metin) {
  const satirlar = metin.split('\n').map(s => s.trim()).filter(s => s.length > 0);
  const sonuc = {};
  let biriktirilenArapca = '';

  for (let i = 0; i < satirlar.length; i++) {
    const satir = satirlar[i];
    const numaraMatch = satir.match(/^(\d+)\.$/); // sadece "7." gibi bir satır

    if (numaraMatch) {
      const ayetNo = parseInt(numaraMatch[1]);
      if (biriktirilenArapca) {
        sonuc[ayetNo] = biriktirilenArapca.trim();
        biriktirilenArapca = '';
      }
    } else {
      // Arapça (veya başka) satır — biriktir (birden fazla satır sürebilir, sûre başlığı gibi olmayan satırlar dahil olabilir)
      biriktirilenArapca += (biriktirilenArapca ? ' ' : '') + satir;
    }
  }

  return sonuc;
}

function _ozelArapcaYukle(sureNo, metin) {
  const parsed = _ozelArapcaParseEt(metin);
  _bellekCache.arapca[_ozelArapcaAnahtari(sureNo)] = parsed;
  return Object.keys(parsed).length;
}

// Sure için özel Arapça var mı? Varsa array olarak (mevcut arData formatında) döndür
function _ozelArapcaGetir(sureNo) {
  const veri = _bellekCache.arapca[_ozelArapcaAnahtari(sureNo)];
  if (!veri) return null;
  return Object.keys(veri).map(no => ({ verse: parseInt(no), arabic: veri[no] }));
}

async function _kurancilarArAl(sNo) {
  // Önce senin GitHub'dan yüklediğin özel Arapça var mı bak — varsa API'ye hiç gitme
  const ozel = _ozelArapcaGetir(sNo);
  if (window._arapcaDebug) {
    alert('Sure ' + sNo + ' için özel Arapça kontrolü: ' + (ozel ? ozel.length + ' ayet bulundu' : 'BULUNAMADI (null)'));
  }
  if (ozel && ozel.length > 0) {
    kurancilarArCache[sNo] = ozel;
    return ozel;
  }

  if (kurancilarArCache[sNo]) return kurancilarArCache[sNo];
  try {
    const url = 'https://kurancilar.github.io/json/sure/' + sNo + '.json';
    const r = await fetch(url);
    const d = await r.json();
    // Format: {verses: [{arabic:"...", ...}]}
    const ayetler = d.verses || d;
    const normalize = Array.isArray(ayetler)
      ? ayetler.map((a, i) => ({ verse: i + 1, arabic: a.arabic || a.ar || a.text || '' }))
      : [];
    kurancilarArCache[sNo] = normalize;
    return normalize;
  } catch(e) {
    kurancilarArCache[sNo] = null;
    return null;
  }
}



// Modal ayet detayı dipnot accordion
function _modalDipnotToggle(dipNo) {
  const wrap = document.getElementById('modal-dipnot-wrap');
  if (!wrap) return;
  const hedefId = 'modal-dipnot-' + dipNo;
  wrap.querySelectorAll('.dipnot-kutu').forEach(kutu => {
    if (kutu.id === hedefId) {
      kutu.style.display = kutu.style.display === 'none' ? 'block' : 'none';
    } else {
      kutu.style.display = 'none';
    }
  });
}

// Dipnot accordion — aynı anda sadece bir dipnot açık (ayet bazında)
function _dipnotToggle(sNo, aNo, dipNo) {
  const wrapId = 'dipnot-wrap-' + sNo + '_' + aNo;
  const wrap = document.getElementById(wrapId);
  if (!wrap) return;
  const hedefId = 'dipnot-' + sNo + '_' + aNo + '_' + dipNo;
  wrap.querySelectorAll('.dipnot-kutu').forEach(kutu => {
    if (kutu.id === hedefId) {
      // Aynı dipnota basılırsa kapat, değilse aç
      kutu.style.display = kutu.style.display === 'none' ? 'block' : 'none';
    } else {
      // Diğerlerini kapat
      kutu.style.display = 'none';
    }
  });
}

