// ════════════════════════════════════════
//  NOT TAM EKRAN OKUMA SAYFASI
// ════════════════════════════════════════
let _notOkumaSNo = null, _notOkumaANo = null, _notOkumaIdx = null;

// ════════════════════════════════════════
//  NOT OKUMA — ARAPÇA BOYUTU
// ════════════════════════════════════════
const NOT_AR_ADIM = [18, 22, 26, 32, 40];
let aktifNotArIdx = parseInt(localStorage.getItem('notOkumaArFs') || '2');

function notOkumaArFsBoyutDegistir(yon) {
  aktifNotArIdx = Math.max(0, Math.min(NOT_AR_ADIM.length - 1, aktifNotArIdx + yon));
  localStorage.setItem('notOkumaArFs', aktifNotArIdx);
  _notOkumaArFsUygula();
}
function _notOkumaArFsUygula() {
  const boyut = NOT_AR_ADIM[aktifNotArIdx] + 'px';
  const overlay = document.getElementById('not-okuma-overlay');
  if (overlay) overlay.style.setProperty('--not-ar-fs', boyut);
  const okumDiv = document.getElementById('not-okuma-metin-div');
  if (okumDiv) okumDiv.style.setProperty('--not-ar-fs', boyut);
  document.querySelectorAll('#not-okuma-icerik [data-ar="1"]').forEach(el => { el.style.fontSize = boyut; });
  const arEl = document.getElementById('not-ar-goster');
  if (arEl) arEl.textContent = boyut;
}

// ════════════════════════════════════════
//  NOT OKUMA — ARKA PLAN
// ════════════════════════════════════════
let _notBgRenk = localStorage.getItem('notBgRenk') || '#f5f0e8';

function notBgSec(renk) {
  _notBgRenk = renk;
  localStorage.setItem('notBgRenk', renk);
  _notBgUygula();
  notBgMenuAcToggle(true); // kapat
}
function _notBgUygula() {
  const overlay = document.getElementById('not-okuma-overlay');
  const icerik = document.getElementById('not-okuma-icerik');
  const alt = document.getElementById('not-okuma-alt');
  const hdr = document.getElementById('not-okuma-header');
  // Koyu arka plan için yazı rengi ayarla
  const koyu = _notBgKoyuMu(_notBgRenk);
  [overlay, icerik, alt, hdr].forEach(el => {
    if (el) {
      el.style.background = _notBgRenk;
      el.style.color = koyu ? '#e8dcc8' : '';
    }
  });
  // İçerik metin rengini de güncelle
  const metinDiv = document.getElementById('not-okuma-metin-div');
  if (metinDiv) metinDiv.style.color = koyu ? '#e8dcc8' : 'var(--ink)';
}
function _notBgKoyuMu(renk) {
  // hex → luminance hızlı hesabı
  const c = renk.replace('#','');
  const r = parseInt(c.substr(0,2),16), g = parseInt(c.substr(2,2),16), b = parseInt(c.substr(4,2),16);
  return (r*0.299 + g*0.587 + b*0.114) < 128;
}
function notBgMenuAcToggle(kapat) {
  const m = document.getElementById('not-bg-menu');
  if (!m) return;
  m.style.display = (kapat || m.style.display !== 'none') ? 'none' : 'block';
  document.getElementById('not-vurgu-menu').style.display = 'none';
}

// ════════════════════════════════════════
//  NOT OKUMA — VURGULAMA
// ════════════════════════════════════════
function notVurguMenuAcToggle(kapat) {
  const m = document.getElementById('not-vurgu-menu');
  if (!m) return;
  m.style.display = (kapat || m.style.display !== 'none') ? 'none' : 'block';
  document.getElementById('not-bg-menu').style.display = 'none';
}
function seciliMetniyiVurgula(sinif) {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return;
  const range = sel.getRangeAt(0);
  // Seçili alan not-okuma-icerik içinde mi kontrol et
  const icerik = document.getElementById('not-okuma-icerik');
  if (!icerik || !icerik.contains(range.commonAncestorContainer)) return;
  const span = document.createElement('span');
  span.className = sinif;
  try {
    range.surroundContents(span);
  } catch(e) {
    // Kısmi seçimlerde alternatif yol
    const frag = range.extractContents();
    span.appendChild(frag);
    range.insertNode(span);
  }
  sel.removeAllRanges();
  notVurguMenuAcToggle(true);
}
function seciliVurguyuKaldir() {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return;
  const node = sel.anchorNode;
  if (!node) return;
  const span = node.nodeType === 3 ? node.parentElement : node;
  if (span && ['vurgu1','vurgu2','vurgu3','vurgu4'].some(c => span.classList.contains(c))) {
    const parent = span.parentNode;
    while (span.firstChild) parent.insertBefore(span.firstChild, span);
    parent.removeChild(span);
  }
  notVurguMenuAcToggle(true);
}

