const _navGecmis = []; // [{tip, veri}]

function _navPush(tip, veri) {
  _navGecmis.push({ tip, veri });
  // browser history'ye de ekle (Android geri tuşu için)
  try { history.pushState({ navIdx: _navGecmis.length }, ''); } catch(e) {}
}

function _navGeriGit() {
  if (_navGecmis.length === 0) return false;
  const son = _navGecmis.pop();
  switch(son.tip) {
    case 'tab':
      tabGec(son.veri, false); // false = geçmişe ekleme
      break;
    case 'notOkuma':
      notOkumaSayfasiKapat(false);
      break;
    case 'notlarModal':
      notlarModalKapat();
      break;
    case 'sure':
      // Sure kapansın
      const kart = document.querySelector('.sure-kart.acik');
      if (kart) sureToggle(null, kart);
      break;
    case 'kumeOkuma':
      okumaModu === true && okumaModunuKapat && okumaModunuKapat();
      break;
  }
  return true;
}

// Browser geri tuşunu yakala
window.addEventListener('popstate', (e) => {
  if (!_navGeriGit()) {
    // Geçmiş bitti, sayfa zaten en başta
    history.pushState({}, '');
  }
});

// Başlangıçta bir state ekle (geri tuşu çalışsın)
try { history.pushState({ navIdx: 0 }, ''); } catch(e) {}

