// ════════════════════════════════════════
//  NOT MARKDOWN RENDERER
//  Söz dizimi:
//    > metin       → sol çizgili alıntı paragrafı
//    >> metin      → tırnaklı vurgu kartı
//    # Başlık      → bölüm başlığı
//    ## Alt Başlık → küçük başlık
//    **kelime**    → kalın/vurgulu
//    ---           → ince ayraç çizgisi
//    [S:A]         → âyet atıf linki
//    Arapça satır  → otomatik ayet kutusu + ayraç
// ════════════════════════════════════════
function _arapcaMi(metin) {
  // Satırın %40'ından fazlası Arapça Unicode ise Arapça say
  const arapca = (metin.match(/[\u0600-\u06FF\u0750-\u077F]/g) || []).length;
  return arapca > metin.length * 0.3;
}

