function mdEkle(tip) {
  const ta = document.getElementById('not-okuma-ta');
  if (!ta) return;
  const start = ta.selectionStart, end = ta.selectionEnd;
  const secili = ta.value.substring(start, end);
  let ekle = '', cursorOffset = 0;
  switch(tip) {
    case 'bold':      ekle = `**${secili||'metin'}**`; cursorOffset = secili ? ekle.length : 2; break;
    case 'alinti':    ekle = `\n> ${secili||'alıntı metni'}`; cursorOffset = ekle.length; break;
    case 'vurgu':     ekle = `\n>> ${secili||'vurgu metni'}`; cursorOffset = ekle.length; break;
    case 'baslik':    ekle = `\n# ${secili||'Başlık'}`; cursorOffset = ekle.length; break;
    case 'altbaslik': ekle = `\n## ${secili||'Alt Başlık'}`; cursorOffset = ekle.length; break;
    case 'ayrac':     ekle = '\n---\n'; cursorOffset = ekle.length; break;
    case 'atif':      ekle = '[[2:255]]'; cursorOffset = 2; break;
    case 'embed':     ekle = '\n{{60:1}}\n'; cursorOffset = 3; break;
  }
  ta.value = ta.value.substring(0, start) + ekle + ta.value.substring(end);
  ta.selectionStart = ta.selectionEnd = start + cursorOffset;
  ta.focus();
  ta.style.height = 'auto';
  ta.style.height = Math.max(200, ta.scrollHeight) + 'px';
}

