// ════════════════════════════════════════
//  ÂYET EMBED SİSTEMİ  {{S:A}} veya {{S:A-B}}
// ════════════════════════════════════════
const _ayetEmbedCache = {};

async function _ayetEmbedGetir(sNo, aNo) {
  const key = sNo + ':' + aNo;
  if (_ayetEmbedCache[key]) return _ayetEmbedCache[key];
  try {
    const [arRes, diyanetAyetler] = await Promise.all([
      fetch(`https://api.acikkuran.com/surah/${sNo}/verse/${aNo}`).then(r=>r.json()).catch(()=>null),
      _fawazSureAl(sNo)
    ]);
    const ar = arRes?.data?.verse || '';
    let meal = '';
    if (Array.isArray(diyanetAyetler)) {
      const v = diyanetAyetler.find(a => a.verse === aNo);
      meal = v?.text || '';
    }
    const sonuc = { ar, meal };
    _ayetEmbedCache[key] = sonuc;
    return sonuc;
  } catch(e) { return { ar:'', meal:'' }; }
}

function _ayetEmbedKutuOlustur(sNo, aNo, ar, meal) {
  const sure = SURELER[sNo-1];
  const kutu = document.createElement('div');
  kutu.style.cssText = `background:rgba(160,120,48,0.07);border:1px solid rgba(160,120,48,0.3);border-radius:14px;padding:16px 18px 14px;margin:16px 0 8px;`;
  const baslik = document.createElement('div');
  baslik.style.cssText = `font-size:11px;font-weight:700;color:var(--gold);letter-spacing:1px;margin-bottom:10px;display:flex;justify-content:space-between;align-items:center;`;
  baslik.innerHTML = `<span>${sure ? sure.isim.toUpperCase() : sNo+'. SÛRE'} ${sNo}:${aNo}</span><span style="font-size:10px;color:var(--muted);font-weight:400;">Diyanet Meali</span>`;
  kutu.appendChild(baslik);
  if (ar) {
    const arDiv = document.createElement('div');
    arDiv.setAttribute('data-ar','1');
    arDiv.style.cssText = `font-family:var(--ar-font);font-size:var(--not-ar-fs,26px);line-height:2;color:var(--ink);direction:rtl;text-align:right;margin-bottom:12px;`;
    arDiv.textContent = ar;
    kutu.appendChild(arDiv);
  }
  const sep = document.createElement('div');
  sep.style.cssText = `width:40px;height:1.5px;margin:0 auto 12px;background:linear-gradient(90deg,transparent,var(--gold),transparent);border-radius:2px;`;
  kutu.appendChild(sep);
  if (meal) {
    const mealDiv = document.createElement('div');
    mealDiv.style.cssText = `font-family:'Source Serif 4',serif;font-size:0.92em;line-height:1.9;color:var(--ink);font-style:italic;`;
    mealDiv.textContent = meal;
    kutu.appendChild(mealDiv);
  }
  if (!ar && !meal) kutu.innerHTML += `<div style="color:var(--muted);font-size:13px;text-align:center;padding:8px;">Âyet yüklenemedi (${sNo}:${aNo})</div>`;
  return kutu;
}

function notMarkdownRender(metin, hedef) {
  hedef.innerHTML = '';
  // Yükleniyor göstergesi
  const yukl = document.createElement('div');
  yukl.style.cssText = 'color:var(--muted);font-size:13px;padding:4px 0;';
  yukl.textContent = '';
  hedef.appendChild(yukl);
  _notMarkdownRenderAsync(metin, hedef, yukl);
}

async function _notMarkdownRenderAsync(metin, hedef, yukl) {
  // {{S:A}} referanslarını önceden çek
  const embedRegex = /\{\{(\d+):(\d+)(?:-(\d+))?\}\}/g;
  const fetchGorevleri = [];
  let m;
  while ((m = embedRegex.exec(metin)) !== null) {
    const sNo = parseInt(m[1]), aB = parseInt(m[2]), aS = m[3] ? parseInt(m[3]) : parseInt(m[2]);
    for (let a = aB; a <= Math.min(aS, aB+9); a++) fetchGorevleri.push(_ayetEmbedGetir(sNo, a));
  }
  if (fetchGorevleri.length > 0) {
    if (yukl) { yukl.textContent = '⏳ Âyetler yükleniyor…'; }
    await Promise.all(fetchGorevleri);
  }
  if (yukl) yukl.remove();

  const satirlar = metin.split('\n');
  let i = 0;

  while (i < satirlar.length) {
    const temiz = satirlar[i].trim();

    if (!temiz) { const b=document.createElement('div'); b.style.height='10px'; hedef.appendChild(b); i++; continue; }

    // {{S:A}} veya {{S:A-B}} → âyet embed
    const embedM = temiz.match(/^\{\{(\d+):(\d+)(?:-(\d+))?\}\}$/);
    if (embedM) {
      const sNo=parseInt(embedM[1]), aB=parseInt(embedM[2]), aS=embedM[3]?parseInt(embedM[3]):aB;
      for (let a=aB; a<=Math.min(aS,aB+9); a++) {
        const veri = await _ayetEmbedGetir(sNo, a);
        hedef.appendChild(_ayetEmbedKutuOlustur(sNo, a, veri.ar, veri.meal));
        if (a < aS) { const ms=document.createElement('div'); ms.style.height='6px'; hedef.appendChild(ms); }
      }
      i++; continue;
    }

    if (temiz==='---') { const hr=document.createElement('div'); hr.style.cssText=`width:50%;height:1.5px;margin:20px auto;background:linear-gradient(90deg,transparent,var(--gold),transparent);border-radius:2px;`; hedef.appendChild(hr); i++; continue; }

    if (_arapcaMi(temiz)) {
      let ar=temiz;
      while (i+1<satirlar.length && _arapcaMi(satirlar[i+1].trim())) { i++; ar+=' '+satirlar[i].trim(); }
      const kutu=document.createElement('div'); kutu.style.cssText=`background:rgba(160,120,48,0.08);border:1px solid rgba(160,120,48,0.25);border-radius:14px;padding:16px 18px 14px;margin:16px 0 8px;`;
      const arDiv=document.createElement('div'); arDiv.setAttribute('data-ar','1'); arDiv.style.cssText=`font-family:var(--ar-font);font-size:var(--not-ar-fs,26px);line-height:2;color:var(--ink);direction:rtl;text-align:right;`; arDiv.textContent=ar;
      kutu.appendChild(arDiv); hedef.appendChild(kutu);
      const sep2=document.createElement('div'); sep2.style.cssText=`width:36px;height:1.5px;margin:10px auto 16px;background:linear-gradient(90deg,transparent,var(--gold),transparent);border-radius:2px;`; hedef.appendChild(sep2);
      i++; continue;
    }

    if (temiz.startsWith('>>')) { const ic=temiz.slice(2).trim(); const kart=document.createElement('div'); kart.style.cssText=`display:flex;gap:12px;align-items:flex-start;background:var(--paper2);border-radius:12px;padding:14px 16px;margin:12px 0;`; const t=document.createElement('div'); t.style.cssText=`width:28px;height:28px;border-radius:50%;background:var(--teal,#1a6050);color:#fff;font-size:14px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:2px;`; t.textContent='❝'; const tx=document.createElement('div'); tx.style.cssText=`font-size:0.95em;line-height:1.9;color:var(--ink);font-style:italic;`; tx.appendChild(_markdownInline(ic)); kart.appendChild(t); kart.appendChild(tx); hedef.appendChild(kart); i++; continue; }

    if (temiz.startsWith('>')) { const ic=temiz.slice(1).trim(); const blok=document.createElement('div'); blok.style.cssText=`border-left:3px solid var(--gold);padding:6px 0 6px 14px;margin:10px 0;color:var(--ink);line-height:1.9;`; blok.appendChild(_markdownInline(ic)); hedef.appendChild(blok); i++; continue; }

    if (temiz.startsWith('## ')) { const el=document.createElement('div'); el.style.cssText=`font-family:'Playfair Display',serif;font-size:1.05em;font-weight:700;color:var(--ink);margin:18px 0 6px;border-bottom:1px solid var(--border);padding-bottom:4px;`; el.textContent=temiz.slice(3); hedef.appendChild(el); i++; continue; }
    if (temiz.startsWith('# '))  { const el=document.createElement('div'); el.style.cssText=`font-family:'Playfair Display',serif;font-size:1.15em;font-weight:700;color:var(--ink);margin:20px 0 8px;border-bottom:2px solid var(--gold);padding-bottom:6px;`; el.textContent=temiz.slice(2); hedef.appendChild(el); i++; continue; }

    const p=document.createElement('p'); p.style.cssText=`margin:0 0 14px;line-height:1.95;`; p.appendChild(_markdownInline(temiz)); hedef.appendChild(p);
    i++;
  }
  setTimeout(()=>_atifLinkleriniGuncelle(hedef), 20);
}

// Satır içi markdown: **bold**, atıf linkleri
function _markdownInline(metin) {
  const frag = document.createDocumentFragment();

  // Önce **bold** işaretle
  const parcalar = metin.split(/(\*\*[^*]+\*\*)/g);
  parcalar.forEach(parca => {
    if (parca.startsWith('**') && parca.endsWith('**')) {
      const bold = document.createElement('strong');
      bold.style.cssText = 'font-weight:700;color:var(--ink);';
      bold.appendChild(atifMetniParsele(parca.slice(2, -2)));
      frag.appendChild(bold);
    } else if (parca) {
      frag.appendChild(atifMetniParsele(parca));
    }
  });
  return frag;
}

let _notOkumaGeldigiYer = null; // 'modal' veya null

function notOkumaSayfasiAc(sNo, aNo, idx, n, geldigiYer) {
  _notOkumaSNo = sNo; _notOkumaANo = aNo; _notOkumaIdx = idx;
  _notOkumaGeldigiYer = geldigiYer || null;

  const overlay = document.getElementById('not-okuma-overlay');
  const sure = SURELER[sNo - 1];

  document.getElementById('not-okuma-sure-adi').textContent =
    (sure ? sure.isim + ' ' : '') + sNo + ':' + aNo;
  document.getElementById('not-okuma-klasor-adi').textContent =
    '📁 ' + (n.isim || 'Klasör ' + (idx + 1));

  _notOkumaIcerigiGoster(n);

  overlay.style.display = 'flex';
  document.body.style.overflow = 'hidden';

  // Arka plan + font uygula
  _notBgUygula();
  _notOkumaArFsUygula();
  _notOkumaFsUygula();
  setTimeout(_notFontUygula, 30);

  // Atıf linklerini görünür yap
  setTimeout(() => {
    _atifLinkleriniGuncelle(document.getElementById('not-okuma-icerik'));
  }, 50);

  // Menüleri dışa tıklayınca kapat
  overlay.onclick = (e) => {
    const bgMenu = document.getElementById('not-bg-menu');
    const vurguMenu = document.getElementById('not-vurgu-menu');
    if (bgMenu && !bgMenu.contains(e.target) && !document.getElementById('not-bg-btn')?.contains(e.target))
      bgMenu.style.display = 'none';
    if (vurguMenu && !vurguMenu.contains(e.target) && !document.getElementById('not-vurgu-btn')?.contains(e.target))
      vurguMenu.style.display = 'none';
  };

  // Geri geçmişe ekle
  _navPush('notOkuma', { sNo, aNo, idx });
}

function _notOkumaIcerigiGoster(n) {
  const icerikEl = document.getElementById('not-okuma-icerik');
  icerikEl.innerHTML = '';

  const mdToolbar = document.getElementById('not-md-toolbar');
  let duzenlemeModu = false;
  let degisiklikVar = false;

  // Klasör adı
  const isimEl = document.createElement('div');
  isimEl.id = 'not-okuma-isim-inp';
  isimEl.contentEditable = 'false';
  isimEl.textContent = n.isim || 'Klasör';
  isimEl.style.cssText = 'padding:8px 14px;border:1px solid transparent;border-radius:10px;font-family:"Playfair Display",serif;font-size:15px;font-weight:700;color:var(--ink);outline:none;margin-bottom:12px;background:transparent;cursor:default;';
  icerikEl.appendChild(isimEl);

  // Okuma div
  const okumDiv = document.createElement('div');
  okumDiv.id = 'not-okuma-metin-div';
  okumDiv.className = 'not-okuma-metin';
  okumDiv.style.cssText = 'font-size:var(--not-okuma-fs,18px);line-height:2.1;color:var(--ink);padding:0 2px;cursor:text;min-height:60px;';
  okumDiv.style.setProperty('--not-ar-fs', NOT_AR_ADIM[aktifNotArIdx] + 'px');
  if (n.icerik && n.icerik.trim()) {
    notMarkdownRender(n.icerik, okumDiv);
  } else {
    okumDiv.innerHTML = '<span style="color:var(--muted);font-style:italic;">Düzenlemek için çift dokunun…</span>';
  }
  icerikEl.appendChild(okumDiv);

  // Textarea — her zaman okuma div'in arkasında hazır
  const ta = document.createElement('textarea');
  ta.id = 'not-okuma-ta';
  ta.value = n.icerik || '';
  ta.placeholder = 'Not yazın…';
  ta.style.cssText = 'display:none;width:100%;box-sizing:border-box;font-family:"Source Serif 4",serif;font-size:var(--not-okuma-fs,18px);line-height:2;color:var(--ink);background:transparent;border:none;outline:none;resize:none;padding:0 2px;overflow:hidden;direction:ltr;unicode-bidi:plaintext;';

  // Input: sadece yüksekliği ayarla, scroll'a dokunma
  ta.addEventListener('input', () => {
    const ic = document.getElementById('not-okuma-icerik');
    const sv = ic ? ic.scrollTop : 0;
    ta.style.height = '1px';
    ta.style.height = ta.scrollHeight + 'px';
    if (ic) ic.scrollTop = sv;
    degisiklikVar = true;
    yeniKaydet.style.display = 'inline-flex';
  });

  _undoKurulum(ta);
  icerikEl.appendChild(ta);

  // Düzenleme modunu aç
  function duzenlemeAc(cursorSon) {
    if (duzenlemeModu) return;
    duzenlemeModu = true;

    // Önce textarea'yı göster ve yüksekliği ayarla
    ta.style.height = '1px';
    ta.style.display = 'block';
    ta.style.height = ta.scrollHeight + 'px';
    okumDiv.style.display = 'none';

    isimEl.contentEditable = 'true';
    isimEl.style.background = 'var(--paper2)';
    isimEl.style.border = '1px solid var(--border)';
    isimEl.style.cursor = 'text';

    if (mdToolbar) { mdToolbar.style.display = 'block'; _undoToolbarEkle(ta); }
    yeniDuzenle.style.display = 'none';

    // Cursor: belirtilmişse oraya, yoksa sona git
    ta.focus();
    const pos = (cursorSon === undefined) ? ta.value.length : cursorSon;
    try { ta.setSelectionRange(pos, pos); } catch(e) {}
  }

  // Okuma moduna dön — scroll'a dokunma
  function okumaModu() {
    duzenlemeModu = false;
    ta.style.display = 'none';
    isimEl.contentEditable = 'false';
    isimEl.style.background = 'transparent';
    isimEl.style.border = '1px solid transparent';
    isimEl.style.cursor = 'default';
    if (mdToolbar) mdToolbar.style.display = 'none';

    okumDiv.innerHTML = '';
    okumDiv.style.display = 'block';
    if (ta.value.trim()) {
      notMarkdownRender(ta.value, okumDiv);
      setTimeout(() => _atifLinkleriniGuncelle(okumDiv), 20);
    } else {
      okumDiv.innerHTML = '<span style="color:var(--muted);font-style:italic;">Düzenlemek için çift dokunun…</span>';
    }
    yeniDuzenle.style.display = 'inline-flex';
  }

  // Dokunulan/tıklanan noktadaki metin pozisyonunu bul
  function _cursorPozBul(x, y) {
    // okumDiv'deki render edilmiş metinden textarea pozisyonunu hesapla
    let node, offset;
    if (document.caretPositionFromPoint) {
      const pos = document.caretPositionFromPoint(x, y);
      if (pos) { node = pos.offsetNode; offset = pos.offset; }
    } else if (document.caretRangeFromPoint) {
      const range = document.caretRangeFromPoint(x, y);
      if (range) { node = range.startContainer; offset = range.startOffset; }
    }
    if (!node) return ta.value.length;

    // Render edilmiş metinden ham textarea metnindeki pozisyonu tahmin et
    // okumDiv'deki tüm text node'larını topla
    const walker = document.createTreeWalker(okumDiv, NodeFilter.SHOW_TEXT);
    let charCount = 0;
    let found = false;
    while (walker.nextNode()) {
      const n = walker.currentNode;
      if (n === node) {
        charCount += offset;
        found = true;
        break;
      }
      charCount += n.textContent.length;
    }
    if (!found) return ta.value.length;

    // Ham metinde aynı oranda pozisyon bul
    const renderLen = okumDiv.textContent.length;
    if (renderLen === 0) return ta.value.length;
    const oran = charCount / renderLen;
    return Math.round(oran * ta.value.length);
  }

  // Çift tıklama — masaüstü
  okumDiv.addEventListener('dblclick', (e) => {
    const pos = _cursorPozBul(e.clientX, e.clientY);
    duzenlemeAc(pos);
  });

  // Çift dokunuş — mobil
  let sonDokun = 0;
  let sonX = 0, sonY = 0;
  okumDiv.addEventListener('touchend', (e) => {
    const simdi = Date.now();
    const t = e.changedTouches[0];
    if (simdi - sonDokun < 350) {
      e.preventDefault();
      const pos = _cursorPozBul(sonX, sonY);
      duzenlemeAc(pos);
    }
    sonDokun = simdi;
    sonX = t.clientX;
    sonY = t.clientY;
  }, { passive: false });

  // Butonları sıfırla (önceki listener'ları temizle)
  const duzenleBtn = document.getElementById('not-okuma-duzenle-btn');
  const kaydetBtn  = document.getElementById('not-okuma-kaydet-btn');
  const silBtn     = document.getElementById('not-okuma-sil-btn');
  const yeniDuzenle = duzenleBtn.cloneNode(true);
  const yeniKaydet  = kaydetBtn.cloneNode(true);
  const yeniSil     = silBtn.cloneNode(true);
  duzenleBtn.parentNode.replaceChild(yeniDuzenle, duzenleBtn);
  kaydetBtn.parentNode.replaceChild(yeniKaydet, kaydetBtn);
  silBtn.parentNode.replaceChild(yeniSil, silBtn);

  yeniKaydet.style.display = 'none';
  yeniDuzenle.textContent = '✏️ Düzenle';

  yeniDuzenle.onclick = () => duzenlemeAc(ta.value.length);

  yeniKaydet.onclick = () => {
    const yeniIcerik = ta.value.trim();
    if (!yeniIcerik) { ta.style.border = '1.5px solid var(--rust)'; ta.focus(); return; }
    const yeniIsim = isimEl.textContent.trim() || n.isim || ('Klasör ' + (_notOkumaIdx + 1));

    // Kaydet
    if (_notOkumaANo === 0) {
      const arr = sureNotlariniGetir(_notOkumaSNo);
      if (arr[_notOkumaIdx]) { arr[_notOkumaIdx].icerik = yeniIcerik; arr[_notOkumaIdx].isim = yeniIsim; }
      localStorage.setItem('an_' + _notOkumaSNo + '_0', JSON.stringify(arr));
    } else {
      const arr = ayetNotlariniGetir(_notOkumaSNo, _notOkumaANo);
      if (arr[_notOkumaIdx]) { arr[_notOkumaIdx].icerik = yeniIcerik; arr[_notOkumaIdx].isim = yeniIsim; }
      localStorage.setItem('an_' + _notOkumaSNo + '_' + _notOkumaANo, JSON.stringify(arr));
      // Ayet notu düzenlendiyse, arka planda GitHub'daki sure dosyasını da güncelle
      _notlarGithubSenkronla(_notOkumaSNo);
    }
    statGuncelle();
    degisiklikVar = false;
    yeniKaydet.style.display = 'none';
    n.icerik = yeniIcerik;
    n.isim = yeniIsim;
    document.getElementById('not-okuma-klasor-adi').textContent = '📁 ' + yeniIsim;

    // Okuma moduna dön — scroll yerinde kalır
    okumaModu();

    // Modal listelerini güncelle
    if (_notOkumaANo === 0) {
      _sureNotModalIcDoldur(_notOkumaSNo);
    } else {
      notlarModalIcDoldur(_notOkumaSNo, _notOkumaANo);
      const pb = document.getElementById('an-btn-' + _notOkumaSNo + '-' + _notOkumaANo);
      if (pb) _ayetNotBtnGuncelle(pb, _notOkumaSNo, _notOkumaANo);
    }
  };

  yeniSil.onclick = () => {
    const arr = _notOkumaANo === 0
      ? sureNotlariniGetir(_notOkumaSNo)
      : ayetNotlariniGetir(_notOkumaSNo, _notOkumaANo);
    if (!confirm('"' + (arr[_notOkumaIdx]?.isim || 'Klasör') + '" silinsin mi?')) return;
    arr.splice(_notOkumaIdx, 1);
    const key = _notOkumaANo === 0
      ? 'an_' + _notOkumaSNo + '_0'
      : 'an_' + _notOkumaSNo + '_' + _notOkumaANo;
    if (arr.length === 0) localStorage.removeItem(key);
    else localStorage.setItem(key, JSON.stringify(arr));
    statGuncelle();
    notOkumaSayfasiKapat();
    if (_notOkumaANo === 0) {
      _sureNotModalIcDoldur(_notOkumaSNo);
    } else {
      notlarModalIcDoldur(_notOkumaSNo, _notOkumaANo);
      const pb = document.getElementById('an-btn-' + _notOkumaSNo + '-' + _notOkumaANo);
      if (pb) _ayetNotBtnGuncelle(pb, _notOkumaSNo, _notOkumaANo);
    }
  };
}

function notOkumaSayfasiKapat(navPushYap) {
  const overlay = document.getElementById('not-okuma-overlay');
  if (!overlay) return;
  overlay.style.display = 'none';
  document.body.style.overflow = '';
  // Toolbar gizle
  const mdToolbar = document.getElementById('not-md-toolbar');
  if (mdToolbar) mdToolbar.style.display = 'none';
  ['not-bg-menu','not-vurgu-menu','not-ayar-panel'].forEach(id => {
    const m = document.getElementById(id);
    if (m) m.style.display = 'none';
  });
  // Geldiği yere geri dön
  if (_notOkumaGeldigiYer === 'sure' && _notOkumaSNo) {
    setTimeout(() => sureNotModalAc(_notOkumaSNo), 80);
  } else if (_notOkumaGeldigiYer === 'modal' && _notOkumaSNo && _notOkumaANo) {
    setTimeout(() => notlarModalAc(_notOkumaSNo, _notOkumaANo), 80);
  }
}

function notlarModalAc(sNo, aNo) {
  const sure = SURELER[sNo - 1];
  document.getElementById('notlar-modal-baslik').textContent =
    (sure ? sure.isim + ' ' : '') + sNo + ':' + aNo + ' — Notlar';
  notlarModalIcDoldur(sNo, aNo);
  document.getElementById('notlar-modal').classList.add('open');
  document.body.style.overflow = 'hidden';
}

